using Godot;
using System;
public partial class MigrationScene {
 MeshInstance3D distantTerrain;int distantX=int.MinValue,distantZ=int.MinValue;
 void ArtHorizon(int cx,int cz){if(cx==distantX&&cz==distantZ)return;distantX=cx;distantZ=cz;if(distantTerrain!=null){RemoveChild(distantTerrain);distantTerrain.QueueFree();}var st=new SurfaceTool();st.Begin(Mesh.PrimitiveType.Triangles);int centerX=cx*64+32,centerZ=cz*64+32;for(int x=centerX-768;x<centerX+768;x+=32)for(int z=centerZ-768;z<centerZ+768;z+=32){if(Math.Abs(x+16-centerX)<160&&Math.Abs(z+16-centerZ)<160||!game.World.InBlock(x,z))continue;Color c=game.World.IsRiver(x,z)?new Color(.08f,.16f,.20f):new Color(.12f,.18f,.095f);foreach(var p in new[]{Ground(x,z),Ground(x+32,z),Ground(x+32,z+32),Ground(x,z),Ground(x+32,z+32),Ground(x,z+32)}){st.SetColor(c);st.AddVertex(p-new Vector3(0,1,0));}}st.GenerateNormals();distantTerrain=new MeshInstance3D{Mesh=st.Commit(),MaterialOverride=TerrainInk(),CastShadow=GeometryInstance3D.ShadowCastingSetting.Off};AddChild(distantTerrain);distantTerrain.Visible=dungeon==null;}
 bool StaticPlacementBlocked(BuildPiece p){var d=p.Def;var q=new PhysicsShapeQueryParameters3D{Shape=new BoxShape3D{Size=new Vector3((float)Math.Max(.04,d.W-.09),(float)Math.Max(.04,d.H-.09),(float)Math.Max(.04,d.D-.09))},Transform=new Transform3D(Basis.FromEuler(new Vector3(0,(float)(p.Yaw*Math.PI/180),0)),new Vector3((float)p.X,(float)p.Y+(float)d.H/2,(float)p.Z)),Exclude=new Godot.Collections.Array<Rid>{player.GetRid()},Margin=.001f};foreach(var hit in GetWorld3D().DirectSpaceState.IntersectShape(q))if(hit["collider"].AsGodotObject() is Node n&&!n.IsInGroup("terrain"))return true;return false;}
}
